        const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        queue<pair<int,int>> q;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] != '1') continue;
                ++count;
                grid[i][j] = '0';
                q.emplace(i, j);
                while (!q.empty()) {
                    auto [r, c] = q.front(); q.pop();
                    for (auto &d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == '1') {
                            grid[nr][nc] = '0';
                            q.emplace(nr, nc);
                        }
                    }
                }
            }
        }
        return count;
    }
};

