from typing import List
class DSU:
    def __init__(self, n: int):
        self.p = list(range(n))
        self.r = [0] * n
    def find(self, x: int) -> int:
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1
        return True
class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid or not grid[0]:
            return 0
        m, n = len(grid), len(grid[0])
        dsu = DSU(m * n)
        count = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1':
                    count += 1
        for i in range(m):
            for j in range(n):
                if grid[i][j] != '1':
                    continue
                cur = i * n + j
                if j + 1 < n and grid[i][j + 1] == '1':
                    if dsu.union(cur, i * n + j + 1):
                        count -= 1
                if i + 1 < m and grid[i + 1][j] == '1':
                    if dsu.union(cur, (i + 1) * n + j):
                        count -= 1
        return count

